INSERT INTO tennis_rules (source_file, rule_id, content, metadata, embedding) VALUES ('2026-rules-of-tennis-english.pdf', '17.
SERVING', '17.
SERVING
When serving in a standard game, the server shall stand behind alternate halves of the
court, starting from the right half of the court in every game.
In a tie-break game, the service shall be served from behind alternate halves of the
court, with the first served from the right half of the court.
The service shall pass over the net and hit the service court diagonally opposite before
the receiver returns it.', '{"source": "2026-rules-of-tennis-english.pdf", "extracted_at": "2026-02-08 16:03:29"}'::jsonb, '[-0.019037335003846103, 0.04583824438802304, -0.025458478868736804, -0.09122289731316782, 0.010879966931449629, 0.028951510463200866, 0.021195885380184354, 0.029595367560482925, -0.004738419336507738, -0.006312427499551125, -0.042461530599486264, 0.017204333970549646, 0.009086409252434478, 0.003632388996679414, 0.16384032974612306, -0.026564992266748553, -0.014020308818443504, -0.02864069962117233, 0.011085039438706071, -0.02039919408857916, 0.03563651993424526, -0.020575869320525547, -0.012522280789678488, 0.019932574277461878, -0.004825377691991968, 0.008226095308245735, 0.04026748684197282, 0.059561313917516144, 0.07562832774999866, 0.029720159019184372, -0.005074969177294541, -0.00637028258479245, -0.015737518114852442, 0.02733132920340095, -0.014034689181250545, 0.018578555677717334, 0.01301576285120085, 0.009427033129514626, -0.014253605015362674, -0.0010185680204854717, -0.042315326245928195, -0.007258695470024716, -0.0017712458401250974, 0.01620244148183496, 5.852941321699535e-05, 0.039391652147530896, -0.002418544834062806, 0.013729121893820383, -0.027716862412036223, 0.016395212370102427, 0.022217374369025506, -0.020867467504332857, -0.004990106872785712, -0.3509787150417767, 0.012642779730644997, -0.020735580111124263, -0.018461368229973487, 0.0054848763469125695, -0.00960864364302924, 0.02725199045245173, -0.03222184178226832, 0.015103233075082318, 0.015164877399631935, -0.015350548926232393, -0.031114680651041473, 0.016941241188946233, 0.0019023335055784435, -0.0169301114872742, -0.07260668485960849, 0.038128073726338696, -0.017554325817771572, -0.006331558420009493, -0.021878361428441417, -0.023585395487201618, 0.02093143715685306, -0.03412701537522955, 0.015066129785559032, -0.0023736560654668937, -0.031912059088200245, 0.021370997827230835, -0.002353791904154721, -0.04353985218042206, 0.028053678543144788, 0.006975238504484358, 