INSERT INTO tennis_rules (source_file, rule_id, content, metadata, embedding) VALUES ('2026-rules-of-tennis-english.pdf', '7. In doubles the appealing player must make their appeal in such a way that either', '7. In doubles the appealing player must make their appeal in such a way that either
play stops or the chair umpire stops play. If an appeal is made to the chair umpire,
then they must first determine that the correct appeal procedure was followed. If
it was not correct or if it was late, then the chair umpire may determine that the
opposing team was deliberately hindered.
8. If a player erases the ball mark before the chair umpire has made a final decision,
they concede the call.', '{"source": "2026-rules-of-tennis-english.pdf", "extracted_at": "2026-02-08 16:04:13"}'::jsonb, '[-0.03323077163519464, 0.010991839659649623, -0.01411745670754292, -0.10513693218562702, 0.03861215828722046, 0.0005267607475325585, -0.027443140353942973, 0.05322239340585529, -0.018502450767734727, -0.0015954204411332612, -0.0048813272680169615, 0.009554298214248046, 0.005683314955307257, 0.007136831841790533, 0.15610812895949952, 0.0068640500296649086, -0.001253850752656083, -0.018164055964901307, -0.015573469810197787, 0.004524936766843629, 0.024693928050738712, -0.01256586489158542, -0.02507679761865404, 0.005301099916501943, -0.0010984373953039307, 0.0015217812936342374, 0.03911348683792892, 0.04091901985499677, 0.07464271200412435, 0.00938882202397602, -0.030782846460404693, -0.010641446583201314, 0.0028653274451613704, 0.03232722527311739, -0.0034008541574206204, 0.01946564094515471, 0.049223289026971595, -0.0025861684684294756, -0.011117396936165258, 0.023336390504844866, 0.011504847009392982, -0.021142814006781755, 0.0025766460372053522, 0.006928926482514668, -0.029738967550508085, 0.04634138006355106, -0.008947836674279782, -0.0002149148472831332, -0.0543025633268556, 0.011783382445706706, 0.037410558920424476, 0.00271494856889669, -0.010260508244258247, -0.3233477555659937, 0.00961892076527459, -0.033296994983285956, 0.0017244306454780212, 0.015495417684651382, 0.020061312085656955, 0.010794841121444486, -0.054275608301200234, 0.03142642851541023, -0.011605589876905745, 0.004132083190283149, 0.03237679690757024, -8.908911281953006e-05, -0.04436432378109593, -0.005805477686004363, -0.0812421922250018, 0.03244117120664556, -0.025395477792395642, 0.0004646257837821974, -0.022366697838385307, -0.01840398034722097, 0.041690578358980525, -0.05007091535297442, 0.01781695522295092, 0.03376443971077633, -0.005817010273200411, 0.031111240989809948, 0.009177206924507698, -0.06442612381024322, 0.04095599569906937, -0.01980465209766013, 0.01848075